__NUXT_JSONP__("/de/2023promo", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v){return {data:[{details:{slug:s,pageTitle:"2023 MLI Diversify Stipendium für Studierende ausschließlich bestimmter Nationalitäten | Mentor Language Institute",pageDescription:t,title:t,subtitle:["MLI strebt immer danach, den bestmöglichen Lernumfeld für seine Studierenden zu bieten. Im Herbst 2023 wird MLI ein spezielles Stipendium\u002Feinen Rabatt ausschließlich für Studierende \u003Cspan style=\"color: red; font-weight: 700;\"\u003Eaus Brasilien, Kolumbien, Spanien, Deutschland und Italien\u003C\u002Fspan\u003E anbieten, um eine ausgewogene Vertretung verschiedener Nationalitäten an der Schule zu erreichen.","Dieses Stipendium wird ausschließlich Studierenden aus Brasilien, Kolumbien, Spanien, Deutschland und Italien angeboten, die MLI während der Monate Juli, August und September 2023 besuchen.","Das Stipendium ist begrenzt und wird nur an jeweils 10 Studierende an jedem Campus (Westwood und Hollywood) angeboten. Die Stipendien werden nach dem Prinzip \"Wer zuerst kommt, mahlt zuerst\" vergeben.","Wenn Sie ausschließlich \u003Cspan style=\"color: red; font-weight: 700;\"\u003Eaus Brasilien, Kolumbien, Spanien, Deutschland und Italien \u003C\u002Fspan\u003E kommen, ermutigen wir Sie, von diesem besonderen Stipendienangebot Gebrauch zu machen, um Ihre Englischkenntnisse am MLI zu verbessern!","Q1.  Wie hoch ist das Stipendium, das ich von MLI erhalten kann?","Bitte finden Sie den speziellen Preis für dieses Diversity-Stipendium.","Regeln","1. Bewerber können sich nur für ihr Programm bewerben (Unterkunft ist nicht obligatorisch). \u003Cbr\u003E Dieser Diversity-Stipendienpreis gilt nur für Ihre erstmalige Immatrikulation. \u003Cbr\u003E 2. (Sie können dieses Stipendium nicht für Ihre Verlängerung verwenden). \u003Cbr\u003E Wenn Sie unsere Wohnungsvermittlung für mehr als 8 Wochen benötigen, gilt dieser spezielle Wohnungspreis \u003Cbr\u003E 3. auch für einen Zeitraum von mehr als 8 Wochen. Bitte fordern Sie ein Angebot über das Kontaktformular an. \u003Cbr\u003E 4. Alle Gebühren müssen bei Ihrer Ankunft bezahlt werden."],questions:{tables:[{title_optional:"=Kurzzeit-Aufenthalt mit Touristenvisum oder ESTA= ",table:{tableMaxCol:c,weeksStudy:"2 Wochen des Studiums",weeksPlan:"2-wöchiger Plan",tbody:[[b,d],["$250",e],["$30",i],["\u003Cb style=\"background-color: #F7DCB4;\"\u003E$380\u003C\u002Fb\u003E",j],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-50%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a]],weeks2Study:"2 Wochen Studentenunterkunft (Wohnheim)",tbody1:[[b,f],["$420",h],["\u003Cb style=\"background-color: #F7DCB4;\"\u003E$520\u003C\u002Fb\u003E",k],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-35%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a],["\u003Cb style=\"background-color: yellow;\"\u003E$900\u003C\u002Fb\u003E",g],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-57%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a]]}},{table:{tableMaxCol:c,weeksStudy:"3 Wochen des Studiums",weeksPlan:"3-wöchiger Plan",tbody:[[b,d],["$375",e],["$35",i],["\u003Cb style=\"background-color: #F7DCB4;\"\u003E$510\u003C\u002Fb\u003E",j],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-53%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a]],weeks2Study:"3 Wochen Studentenunterkunft (Wohnheim)",tbody1:[[b,f],["$630",h],["\u003Cb style=\"background-color: #F7DCB4;\"\u003E$730\u003C\u002Fb\u003E",k],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-34%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a],["\u003Cb style=\"background-color: yellow;\"\u003E$1,240\u003C\u002Fb\u003E",g],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-43%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a]]}},{table:{tableMaxCol:c,weeksStudy:"4 Wochen des Studiums",weeksPlan:"4wöchiger Plan",tbody:[[b,d],["$400",e],["$40",i],["\u003Cb style=\"background-color: #F7DCB4;\"\u003E$540\u003C\u002Fb\u003E",j],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-61%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a]],weeks2Study:"4 Wochen Studentenunterkunft (Wohnheim)",tbody1:[[b,f],["$840",h],["\u003Cb style=\"background-color: #F7DCB4;\"\u003E$940\u003C\u002Fb\u003E",k],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-33%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a],["\u003Cb style=\"background-color: yellow;\"\u003E$1,480\u003C\u002Fb\u003E",g],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-47%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a]]}},{title_optional:"Längerfristiger Aufenthalt mit Studentenvisum",table:{tableMaxCol:c,weeksStudy:"12 Wochen des Studiums",weeksPlan:"12 wöchiger Plan",tbody:[[l,d],["$1,721",e],["\u003Cb style=\"background-color: #F7DCB4;\"\u003E$1,871\u003C\u002Fb\u003E",m],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-41%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a]],weeks2Study:n,tbody1:[[b,f],[o,h],[p,q],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-30%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a],["\u003Cb style=\"background-color: yellow;\"\u003E$3,483\u003C\u002Fb\u003E",g],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-37%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a]]}},{table:{tableMaxCol:c,weeksStudy:"24 Wochen des Studiums",weeksPlan:"24 wöchiger Plan",tbody:[[l,d],["$3,125",e],["\u003Cb style=\"background-color: #F7DCB4;\"\u003E$3,275\u003C\u002Fb\u003E",m],[r,a]],weeks2Study:n,tbody1:[[b,f],[o,u],[p,q],[v,a],["\u003Cb style=\"background-color: yellow;\"\u003E$4,887\u003C\u002Fb\u003E",g],["\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-63%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E",a]]}},{table:{tableMaxCol:c,weeksStudy:"48 Wochen des Studiums",weeksPlan:"48 wöchiger Plan",tbody:[[l,d],["$5,789",e],["\u003Cb style=\"background-color: #F7DCB4;\"\u003E$5,939\u003C\u002Fb\u003E",m],[r,a]],weeks2Study:n,tbody1:[[b,f],[o,u],[p,q],[v,a],["\u003Cb style=\"background-color: yellow;\"\u003E$7,551\u003C\u002Fb\u003E",g],[r,a]]}}]},qa:[{question:"Q2. Wie kann ich dieses Stipendium erhalten?",answer:["Sie können sich für Ihr Stipendium über unser \u003Cspan style=\"background-color: #F7DCB4;\"\u003EOnline-Bewerbungsformular\u003C\u002Fspan\u003E  unter Verwendung des Codes \u003Cb\u003E\"SCHOLAR2023\"\u003C\u002Fb\u003E bewerben. \u003Cbr\u003E Für die Bearbeitungsgebühr (nicht erstattungsfähig) zahlen Sie lediglich 150 US-Dollar und erhalten einen Gutschrift von 50 US-Dollar, sofern Sie kein F1-Student sind. \u003Cbr\u003E Am ersten Schultag bei MLI zahlen Sie den Restbetrag abzüglich 50 US-Dollar."],btn:"\u002Fimages\u002Fhome\u002Fimage1.png",btn_link:"\u002Fde\u002Fadmission"},{question:"Q3. Welche Programme kann ich mit diesem Stipendium belegen?",answer:["Sie haben die Möglichkeit, entweder am ESL-Programm (9:00 Uhr - 13:15 Uhr) oder am Konversationsprogramm (13:45 Uhr - 18:00 Uhr) teilzunehmen.","- \u003Ca href=\"\u002Fdocuments\u002F2023\u002FMLI WW Class schedule 2023.pdf\"\u003EWestwood Programmplan \u003C\u002Fa\u003E \u003Cbr\u003E - \u003Ca href=\"\u002Fdocuments\u002F2023\u002FMLI HW Class schedule 2023.pdf\"\u003EHollywood Programmplan \u003C\u002Fa\u003E"]},{question:"Q4. Bietet MLI Wohnmöglichkeiten an?",answer:["a, wir bieten Homestay-Optionen sowie Studentenwohnheime und Studentenwohnungen an. \u003Cbr\u003E Bitte besuchen Sie den \u003Ca href=\"\u002Fde\u002Fstay\"\u003Ehier\u003C\u002Fa\u003E.","Bitte kontaktieren Sie uns, wenn Sie Fragen haben!"],btn:"\u002Fimages\u002Fhome\u002Fimage2.png",btn_link:"\u002Fde\u002Fcontact"}],dir:"\u002F2023promo",path:"\u002F2023promo\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:28.391Z",updatedAt:"2025-05-26T12:06:27.569Z"},lang:s}],fetch:{},mutations:void 0}}("\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003Egeringer als reguläre Gebühren\u003C\u002Fb\u003E\u003C\u002Fspan\u003E","$100",3,"Bearbeitungsgebühr","Studiengebühr","Vermittlungsgebühr","\u003Cb style=\"background-color: yellow;\"\u003EGesamtkosten für Schule und Unterkunft\u003C\u002Fb\u003E","Miete (Viererzimmer: 4 Zimmer)","Mietgebühr für Lehrbücher","\u003Cb style=\"background-color: #F7DCB4;\"\u003EGesamtkosten für die Schule\u003C\u002Fb\u003E","\u003Cb style=\"background-color: #F7DCB4;\"\u003EGesamtkosten für die Unterkunft \u003C\u002Fb\u003E","$150","\u003Cb style=\"background-color: #F7DCB4;\"\u003ESchulgesamtkosten\u003C\u002Fb\u003E","8 ochen Studentenunterkunft (Wohnheim):","$1,512","\u003Cb style=\"background-color: #F7DCB4;\"\u003E$1,612\u003C\u002Fb\u003E","\u003Cb style=\"background-color: #F7DCB4;\"\u003EGesamtkosten für Unterkunft \u003C\u002Fb\u003E","\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-39%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E","de","2023 MLI Diversify Stipendium für Studierende ausschließlich bestimmter Nationalitäten","Miete (Viererzimmer: 4 Zimmer) für 8 Wochen","\u003Cspan style=\"color: red;\"\u003E\u003Cb\u003E-32%\u003C\u002Fb\u003E\u003C\u002Fspan\u003E")));